+export interface Record {
+  id: string;
+  path: string;
+  title: string;
+  content: string;
+}
+
+export const project = (records: readonly Record[]): string => {
+  if (records.length === 0) return "";
+
+  const formatted = records
+    .map((r) => `[${r.id}] ${r.title}\n${r.content}`)
+    .join("\n\n");
+
+  return `CommitLore context for file(s):\n\n${formatted}`;
+};
