+import { Server } from "@modelcontextprotocol/sdk/server/index.js";
+import {
+  CallToolRequestSchema,
+  ListToolsRequestSchema,
+  TextContent,
+  Tool,
+} from "@modelcontextprotocol/sdk/types.js";
+import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
+import { injectForPath } from "../core/inject.ts";
+import type { Record } from "../core/project.ts";
+
+const server = new Server({
+  name: "commitlore",
+  version: "1.0.0",
+});
+
+const tools: Tool[] = [
+  {
+    name: "commitlore_records",
+    description: "Get CommitLore records for a file path",
+    inputSchema: {
+      type: "object" as const,
+      properties: {
+        repo: {
+          type: "string",
+          description: "Repository path",
+        },
+        filePath: {
+          type: "string",
+          description: "File path to get records for",
+        },
+      },
+      required: ["repo", "filePath"],
+    },
+  },
+];
+
+server.setRequestHandler(ListToolsRequestSchema, async () => ({
+  tools,
+}));
+
+server.setRequestHandler(CallToolRequestSchema, async (request) => {
+  if (request.params.name === "commitlore_records") {
+    const repo = request.params.arguments?.repo;
+    const filePath = request.params.arguments?.filePath;
+
+    if (typeof repo !== "string" || typeof filePath !== "string") {
+      return {
+        content: [
+          {
+            type: "text" as const,
+            text: "Error: repo and filePath must be strings",
+          },
+        ],
+        isError: true,
+      };
+    }
+
+    try {
+      const injected = injectForPath(repo, filePath);
+      return {
+        content: [
+          {
+            type: "text" as const,
+            text: injected || "No records found for this path",
+          },
+        ],
+      };
+    } catch (error) {
+      return {
+        content: [
+          {
+            type: "text" as const,
+            text: `Error: ${error instanceof Error ? error.message : "Unknown error"}`,
+          },
+        ],
+        isError: true,
+      };
+    }
+  }
+
+  return {
+    content: [
+      {
+        type: "text" as const,
+        text: "Unknown tool",
+      },
+    ],
+    isError: true,
+  };
+});
+
+const transport = new StdioServerTransport();
+await server.connect(transport);
