+import { execSync } from "child_process";
+import { injectForPath } from "../core/inject.ts";
+
+export interface ProactiveInjectionOptions {
+  repo: string;
+  maxFiles?: number;
+}
+
+export const getWorkingFileSet = (repo: string): string[] => {
+  try {
+    const modified = execSync("git diff --name-only", {
+      cwd: repo,
+      encoding: "utf-8",
+    })
+      .trim()
+      .split("\n")
+      .filter(Boolean);
+
+    const staged = execSync("git diff --cached --name-only", {
+      cwd: repo,
+      encoding: "utf-8",
+    })
+      .trim()
+      .split("\n")
+      .filter(Boolean);
+
+    const untracked = execSync("git ls-files -o --exclude-standard", {
+      cwd: repo,
+      encoding: "utf-8",
+    })
+      .trim()
+      .split("\n")
+      .filter(Boolean);
+
+    return Array.from(new Set([...modified, ...staged, ...untracked])).filter(
+      Boolean
+    );
+  } catch {
+    return [];
+  }
+};
+
+export const proactivelyInjectRecords = (
+  options: ProactiveInjectionOptions
+): string => {
+  const files = getWorkingFileSet(options.repo);
+  const limited = files.slice(0, options.maxFiles ?? 10);
+
+  const injected = limited
+    .map((filePath) => injectForPath(options.repo, filePath))
+    .filter(Boolean)
+    .join("\n\n---\n\n");
+
+  if (!injected) return "";
+
+  return `Context for uncommitted changes:\n\n${injected}`;
+};
